{{-- Design table(): rows = [['cells' => [html...], 'search' => text|null]] --}}
<div class="tablewrap"><table><thead><tr>@foreach($headers as $h)<th>{{ $h }}</th>@endforeach</tr></thead><tbody>@forelse($rows as $r)<tr @isset($r['search']) data-search="{{ $r['search'] }}" @endisset>@foreach($r['cells'] as $c)<td>{!! $c !!}</td>@endforeach</tr>@empty<tr><td colspan="{{ count($headers) }}" class="empty">No records found</td></tr>@endforelse @if($rows && collect($rows)->contains(fn ($r) => isset($r['search'])))<tr class="noresult" style="display:none"><td colspan="{{ count($headers) }}" class="empty">No records found</td></tr>@endif</tbody></table></div>
